CREATE OR REPLACE FUNCTION public.cms_default_perms(_key text) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT jsonb_build_object('text',true,'images',true,'forms',true,'stats',true,'blocks',_key IN ('webbuilder','advanced'),'translate',_key IN ('webbuilder','advanced'),'activity',_key IN ('webbuilder','advanced'),'pages',_key='webbuilder','settings',_key='webbuilder','backups',_key='webbuilder','users',false,'dns',false,'updates',false,'restore',_key='webbuilder','buttonColors',_key='webbuilder') $$;
CREATE OR REPLACE FUNCTION public.has_perm(_user_id uuid,_perm text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR (_perm NOT IN ('users','dns','updates') AND EXISTS (SELECT 1 FROM public.user_roles ur LEFT JOIN public.cms_roles c ON c.id=ur.cms_role_id WHERE ur.user_id=_user_id AND ur.role='editor' AND CASE WHEN _perm IN ('restore','buttonColors') THEN c.system_key='webbuilder' ELSE COALESCE(((CASE WHEN c.system_key IS NOT NULL THEN public.cms_default_perms(c.system_key) ELSE c.perms END)->>_perm)::boolean,_perm IN ('text','images','forms','stats')) END)) $$;
CREATE OR REPLACE FUNCTION public.my_perms() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_object_agg(k,public.has_perm(auth.uid(),k)) FROM unnest(ARRAY['text','images','forms','stats','blocks','translate','activity','pages','settings','backups','users','dns','updates','restore','buttonColors']) k $$;
CREATE OR REPLACE FUNCTION public.restore_site_backup(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b jsonb; BEGIN IF NOT public.has_perm(auth.uid(),'restore') THEN RAISE EXCEPTION 'Alleen Administrator en Webbouwer kunnen een back-up terugzetten'; END IF; SELECT data INTO b FROM site_backups WHERE id=_id; IF b IS NULL THEN RAISE EXCEPTION 'Back-up niet gevonden'; END IF;
IF b ? 'custom_pages' THEN
DELETE FROM page_content WHERE path IN (SELECT path FROM custom_pages); DELETE FROM page_seo WHERE path IN (SELECT path FROM custom_pages); DELETE FROM page_settings WHERE path IN (SELECT path FROM custom_pages); DELETE FROM custom_pages WHERE path IS NOT NULL; INSERT INTO custom_pages SELECT * FROM jsonb_populate_recordset(NULL::public.custom_pages,b->'custom_pages');
END IF;
DELETE FROM page_content WHERE path IS NOT NULL; DELETE FROM page_seo WHERE path IS NOT NULL; DELETE FROM page_settings WHERE path IS NOT NULL;
INSERT INTO page_content SELECT * FROM jsonb_populate_recordset(NULL::public.page_content,b->'page_content'); INSERT INTO page_seo SELECT * FROM jsonb_populate_recordset(NULL::public.page_seo,b->'page_seo'); INSERT INTO page_settings SELECT * FROM jsonb_populate_recordset(NULL::public.page_settings,b->'page_settings'); END $$;
CREATE FUNCTION public.guard_button_colors() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE previous jsonb; BEGIN IF auth.uid() IS NULL OR public.has_perm(auth.uid(),'buttonColors') THEN RETURN NEW; END IF; IF TG_OP='UPDATE' THEN previous=OLD.data; ELSE SELECT data INTO previous FROM public.page_content WHERE path=NEW.path AND state<>NEW.state LIMIT 1; END IF; IF EXISTS(SELECT 1 FROM (SELECT key,value->'buttonBackground' bg,value->'buttonForeground' fg FROM jsonb_each(COALESCE(NEW.data,'{}'::jsonb))) n FULL JOIN (SELECT key,value->'buttonBackground' bg,value->'buttonForeground' fg FROM jsonb_each(COALESCE(previous,'{}'::jsonb))) p USING(key) WHERE n.bg IS DISTINCT FROM p.bg OR n.fg IS DISTINCT FROM p.fg) THEN RAISE EXCEPTION 'Alleen Administrator en Webbouwer mogen knopkleuren aanpassen'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_button_colors BEFORE INSERT OR UPDATE ON public.page_content FOR EACH ROW EXECUTE FUNCTION public.guard_button_colors();
REVOKE EXECUTE ON FUNCTION public.guard_button_colors() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.cms_default_perms(text) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.has_perm(uuid,text),public.my_perms(),public.restore_site_backup(uuid) TO authenticated;